    sha,typ,size=parts[0],parts[1],int(parts[2])
    objs[sha]=(typ,data[pos:pos+size]); pos+=size+1
print("readable:",len(objs)," unreadable:",len(missing))
types=collections.Counter(t for t,_ in objs.values()); print("readable by type:",dict(types))
for m in missing: print("  UNREADABLE", m)
# referrers
refs=collections.defaultdict(list)
for sha,(typ,body) in objs.items():
    if typ=='tree':
        i=0
        while i<len(body):
            sp=body.index(b' ',i); nul=body.index(b'\0',sp); mode=body[i:sp].decode(); name=body[sp+1:nul].decode(); child=body[nul+1:nul+21].hex(); i=nul+21
            refs[child].append(('tree',sha,mode,name))
    elif typ=='commit':
        for line in body.split(b'\n'):
            if line.startswith(b'tree '): refs[line[5:45].decode()].append(('commit-tree',sha))
            elif line.startswith(b'parent '): refs[line[7:47].decode()].append(('commit-parent',sha))
            elif line==b'': break
    elif typ=='tag':
        refs[body.split(b'\n')[0][7:47].decode()].append(('tag',sha))
print("\n=== referrers of unreadable objects ===")
for m in missing:
    print(m, subprocess.run(['git','cat-file','-t',m],capture_output=True,text=True).stdout.strip())
    for r in refs.get(m,[]): print("     <-",r)
# commit graph info
print("\n=== commits: author vs committer convention ===")
same=0; diff=0; ex=[]
commits={}
for sha,(typ,body) in objs.items():
    if typ!='commit': continue
    txt=body.decode(errors='replace'); head,_,msg=txt.partition('\n\n')
    a=[l for l in head.split('\n') if l.startswith('author ')][0][7:]
    c=[l for l in head.split('\n') if l.startswith('committer ')][0][10:]
    parents=[l[7:] for l in head.split('\n') if l.startswith('parent ')]
    tree=[l[5:] for l in head.split('\n') if l.startswith('tree ')][0]
    commits[sha]=(tree,parents,a,c,msg)
    if a==c: same+=1
    else: diff+=1; ex.append((sha,a,c))
print("author==committer:",same," differ:",diff)
for e in ex[:10]: print("  differ:",e)
# which unreadable commits are referenced as parents, and by whom
print("\n=== unreadable commits: children ===")
for m in missing:
    for r in refs.get(m,[]):
        if r[0]=='commit-parent':
            ch=r[1]; print(m,"<- child",ch,commits[ch][2],"|",commits[ch][4].strip().splitlines()[0])
# extra: commits with multiple trees - list commits whose tree is unreadable
import pickle; pickle.dump((objs,commits,refs,missing),open('/tmp/census.pkl','wb'))
